import React from 'react'

export default function About() {
  return (
    <div className='container-fluid p-5'>
        <h1>Inventory Management System - MERN CRUD App</h1>
        <p>An Inventory Management System (IMS) is a software solution that helps businesses track, manage, and update their product data efficiently.
              In this project, we’ll build an IMS using the MERN stack — MongoDB, Express.js, React.js, and Node.js — with full CRUD functionality (Create, Read, Update, Delete).</p>
        <p>...</p>
    </div>
  )
}
